                    cands[nt] = (w, match, cand_alt)
        print(f'  candidates: {len(cands)}', flush=True)
        if not cands:
            print('no candidates')
            break
        def ev(nt):
            return (score(nt), nt, cands[nt])
        with ThreadPoolExecutor(max_workers=workers) as ex:
            results = list(ex.map(ev, list(cands.keys())))
        results.sort(key=lambda t: (t[0][0], t[0][1]))
        top, txt, desc = results[0]
        if (top[0], top[1]) < (best[0], best[1]):
