            best = top
        else:
            print(f'round {it}: stuck; best candidate {top[0]}({top[1]:.2f}) vs cur {best[0]}({best[1]:.2f})')
            break
    print('FINAL:', best[0], f'{best[1]:.2f}pt', best[2], flush=True)
    with open('/app/input.tex.final', 'w') as f:
        f.write(cur)

